//! Compile-time coverage for the code generated by `#[plugin]`.
//!
//! The expansion tests in the crate verify classification; this test makes the generated
//! `Plugin` implementation itself compile for the edge cases that need special handling.

use std::sync::atomic::{AtomicUsize, Ordering};
use std::time::Duration;

use clap::Parser;
use tokio::io::{AsyncBufReadExt, BufReader};
use tokio::net::TcpListener;
use tokio::time::timeout;
use zeta_plugin::{
    Client, CommandEvent, Context, CtcpEvent, Error, Event, JoinEvent, KickEvent, MessageEvent,
    NickEvent, PartEvent, Plugin, QuitEvent, RawEvent, Subscriptions, UrlEvent, plugin,
};

/// A plugin whose command and URL handler are gated out.
#[derive(Default)]
struct Gated;

#[plugin(name = "gated", urls(any))]
impl Gated {
    #[cfg(any())]
    #[command(".gated", "A command compiled out by cfg")]
    async fn gated(&self, _: &Context, _: &Client, _: &str) -> Result<(), Error> {
        Ok(())
    }

    #[cfg(any())]
    #[handler(url)]
    async fn url(&self, _: &Context, _: &Client, _: &UrlEvent) -> Result<(), Error> {
        Ok(())
    }
}

/// A plugin with a zero-argument helper named `new`; it is not the plugin constructor.
#[derive(Default)]
struct Helper;

#[plugin(name = "helper")]
impl Helper {
    const fn new() -> Self {
        Self
    }

    #[command(".helper", "A helper constructor")]
    async fn helper(&self, _: &Context, _: &Client, _: &str) -> Result<(), Error> {
        Ok(())
    }
}

/// Options for the free-form `words` command.
#[derive(Parser)]
struct WordsOptions {
    /// the words to echo
    #[allow(dead_code)]
    words: Vec<String>,
}

/// A plugin using the `words` argument mode.
#[derive(Default)]
struct Words;

#[plugin(name = "words")]
impl Words {
    #[command(".words", "Echo the words", args = WordsOptions, words)]
    async fn words(
        &self,
        _: &Context,
        _: &Client,
        _: &str,
        _options: WordsOptions,
    ) -> Result<(), Error> {
        Ok(())
    }
}

/// Options for the full command.
#[derive(Parser)]
struct FullOptions {
    /// the value to echo
    #[allow(dead_code)]
    value: String,
}

/// The hosts the full plugin handles URLs for.
const FULL_HOSTS: &[&str] = &["example.com"];

/// A plugin exercising every generated shape: a recognized constructor, URL hosts, messages,
/// a command with options and the event, and both lifecycle handlers.
struct Full;

#[plugin(name = "full", urls(hosts = FULL_HOSTS), messages)]
impl Full {
    fn new(_: &Context, subscriptions: &mut Subscriptions) -> Result<Self, Error> {
        subscriptions.receive_join();

        Ok(Self)
    }

    #[command(
        ".full",
        "A full command",
        args = FullOptions,
        event,
        label = "Full",
        spec = FULL,
        usage = "Usage: .full <value>",
        register_if = true
    )]
    async fn full(
        &self,
        _: &Context,
        _: &Client,
        _: &str,
        _: &CommandEvent,
        _options: FullOptions,
    ) -> Result<(), Error> {
        Ok(())
    }

    #[command(".event", "An event command without the channel", args = FullOptions, event)]
    async fn event_only(
        &self,
        _: &Context,
        _: &Client,
        _: &CommandEvent,
        _options: FullOptions,
    ) -> Result<(), Error> {
        Ok(())
    }

    #[handler(join)]
    async fn join(&self, _: &Context, _: &Client, _: &JoinEvent) -> Result<(), Error> {
        Ok(())
    }

    #[handler(loaded)]
    async fn loaded(&mut self, _: &Context, _: &Client) -> Result<(), Error> {
        Ok(())
    }

    #[handler(shutdown)]
    async fn shutdown(&mut self, _: &Context, _: &Client) -> Result<(), Error> {
        Ok(())
    }
}

/// A plugin deriving its usage reply from the argument hint.
#[derive(Default)]
struct Hinted {
    /// The number of times the command handler ran: the derived reply must preempt it.
    calls: AtomicUsize,
}

#[plugin(name = "hinted")]
impl Hinted {
    #[command(".hint", "A command with a usage hint", event, usage_hint = "<query>")]
    async fn hint(&self, _: &Context, _: &Client, _: &CommandEvent) -> Result<(), Error> {
        self.calls.fetch_add(1, Ordering::SeqCst);

        Ok(())
    }
}

/// A plugin with one handler per event kind.
///
/// The macro derives each `Event` variant and event type from the kind keyword, so this is what
/// verifies every derived name against the real `Plugin` trait — including the kinds no bundled
/// plugin uses yet.
#[derive(Default)]
struct Kinds;

#[plugin(name = "kinds", urls(any))]
impl Kinds {
    #[handler(command)]
    async fn command(&self, _: &Context, _: &Client, _: &CommandEvent) -> Result<(), Error> {
        Ok(())
    }

    #[handler(url)]
    async fn url(&self, _: &Context, _: &Client, _: &UrlEvent) -> Result<(), Error> {
        Ok(())
    }

    #[handler(message)]
    async fn message(&self, _: &Context, _: &Client, _: &MessageEvent) -> Result<(), Error> {
        Ok(())
    }

    #[handler(join)]
    async fn join(&self, _: &Context, _: &Client, _: &JoinEvent) -> Result<(), Error> {
        Ok(())
    }

    #[handler(part)]
    async fn part(&self, _: &Context, _: &Client, _: &PartEvent) -> Result<(), Error> {
        Ok(())
    }

    #[handler(quit)]
    async fn quit(&self, _: &Context, _: &Client, _: &QuitEvent) -> Result<(), Error> {
        Ok(())
    }

    #[handler(nick)]
    async fn nick(&self, _: &Context, _: &Client, _: &NickEvent) -> Result<(), Error> {
        Ok(())
    }

    #[handler(kick)]
    async fn kick(&self, _: &Context, _: &Client, _: &KickEvent) -> Result<(), Error> {
        Ok(())
    }

    #[handler(ctcp)]
    async fn ctcp(&self, _: &Context, _: &Client, _: &CtcpEvent) -> Result<(), Error> {
        Ok(())
    }

    #[handler(raw)]
    async fn raw(&self, _: &Context, _: &Client, _: &RawEvent) -> Result<(), Error> {
        Ok(())
    }

    #[handler(loaded)]
    async fn loaded(&mut self, _: &Context, _: &Client) -> Result<(), Error> {
        Ok(())
    }

    #[handler(shutdown)]
    async fn shutdown(&mut self, _: &Context, _: &Client) -> Result<(), Error> {
        Ok(())
    }
}

#[test]
fn helper_constructor_remains_callable() {
    let _ = Helper::new();
}

/// A plugin whose recognized constructor takes only a subset of the trait's parameters, in a
/// non-trait order.
struct Partial;

#[plugin(name = "partial", urls(any))]
impl Partial {
    fn new(subscriptions: &mut Subscriptions, _: &Context) -> Result<Self, Error> {
        subscriptions.receive_join();

        Ok(Self)
    }
}

/// Asserts that the generated implementation implements `Plugin`.
///
/// `handle` is a generated method with an `impl Future + Send` return type, so naming the bound
/// here is what checks the spelling; a plain `Registered` bound would not.
const fn assert_plugin<P: Plugin>() {}
#[test]
fn every_plugin_shape_implements_plugin() {
    assert_plugin::<Full>();
    assert_plugin::<Gated>();
    assert_plugin::<Helper>();
    assert_plugin::<Hinted>();
    assert_plugin::<Kinds>();
    assert_plugin::<Partial>();
    assert_plugin::<Words>();
}

/// A plugin recording which generated `handle` arm ran.
#[derive(Default)]
struct Routing {
    /// The number of command events routed to the `#[command]` dispatch.
    command: AtomicUsize,
    /// The number of message events routed to the `#[handler(message)]` method.
    message: AtomicUsize,
    /// The number of `loaded` hooks routed to the `#[handler(loaded)]` method.
    loaded: AtomicUsize,
}

#[plugin(name = "routing")]
impl Routing {
    #[command(".route", "Route a command")]
    async fn route(&self, _: &Context, _: &Client, _: &str) -> Result<(), Error> {
        self.command.fetch_add(1, Ordering::SeqCst);

        Ok(())
    }

    #[handler(message)]
    async fn message(&self, _: &Context, _: &Client, _: &MessageEvent) -> Result<(), Error> {
        self.message.fetch_add(1, Ordering::SeqCst);

        Ok(())
    }

    #[handler(loaded)]
    async fn loaded(&mut self, _: &Context, _: &Client) -> Result<(), Error> {
        self.loaded.fetch_add(1, Ordering::SeqCst);

        Ok(())
    }
}

fn message(text: &str) -> MessageEvent {
    MessageEvent::new(std::sync::Arc::new(
        irc::proto::Message::new(
            Some("nick!user@host.example"),
            "PRIVMSG",
            vec!["#test", text],
        )
        .expect("message should parse"),
    ))
}

fn command(spec: zeta_plugin::CommandSpec) -> CommandEvent {
    CommandEvent::new(
        std::sync::Arc::new(
            irc::proto::Message::new(
                Some("nick!user@host.example"),
                "PRIVMSG",
                vec!["#test", spec.trigger()],
            )
            .expect("message should parse"),
        ),
        spec,
    )
    .expect("command should match")
}

#[tokio::test]
async fn the_generated_handle_routes_each_event_kind() {
    let ctx = zeta_test_support::test_context();
    let client = zeta_test_support::mock_client().await;
    let mut plugin = Routing::default();

    plugin.loaded(&ctx, &client).await.expect("load");

    plugin
        .handle(&ctx, &client, &Event::Message(message("hello")))
        .await
        .expect("message");
    plugin
        .handle(&ctx, &client, &Event::Command(command(ROUTE)))
        .await
        .expect("command");

    assert_eq!(plugin.loaded.load(Ordering::SeqCst), 1);
    assert_eq!(plugin.message.load(Ordering::SeqCst), 1);
    assert_eq!(plugin.command.load(Ordering::SeqCst), 1);
}

/// How long a reply has to reach the test listener before the test gives up.
const DELIVERY_TIMEOUT: Duration = Duration::from_secs(5);

/// Returns a client whose sent lines are readable from the returned listener socket.
///
/// The mock connection's sent log is private to the `irc` crate, so replies are captured on a
/// real socket instead.
async fn capturing_client() -> (Client, tokio::net::TcpStream) {
    let listener = TcpListener::bind("127.0.0.1:0")
        .await
        .expect("bind the test listener");
    let address = listener.local_addr().expect("the listener has an address");

    let mut client = Client::from_config(irc::client::data::Config {
        nickname: Some("zeta-test".to_owned()),
        server: Some(address.ip().to_string()),
        port: Some(address.port()),
        // `use_tls` defaults to true when a TLS feature is enabled, which would hang the
        // handshake against this plain listener.
        use_tls: Some(false),
        ..Default::default()
    })
    .await
    .expect("the client connects to the test listener");

    // Without the outgoing future being driven, the enqueued commands never reach the socket.
    let outgoing = client.outgoing().expect("the outgoing future is available");
    tokio::spawn(async move {
        let _ = outgoing.await;
    });

    let (socket, _) = listener.accept().await.expect("the client connects");

    (client, socket)
}

#[tokio::test]
async fn an_empty_invocation_replies_with_the_derived_usage_line() {
    let ctx = zeta_test_support::test_context();
    let (client, socket) = capturing_client().await;
    let plugin = Hinted::default();

    plugin
        .handle(&ctx, &client, &Event::Command(command(HINT)))
        .await
        .expect("an empty invocation replies and succeeds");

    let mut reply = String::new();
    timeout(
        DELIVERY_TIMEOUT,
        BufReader::new(socket).read_line(&mut reply),
    )
    .await
    .expect("the reply reaches the socket in time")
    .expect("the reply reads as a line");

    assert_eq!(
        reply, "PRIVMSG #test :\x0310> Usage: .hint\x0f <query>\r\n",
        "the line colors the trigger and resets before the hint"
    );
    assert_eq!(
        plugin.calls.load(Ordering::SeqCst),
        0,
        "the usage reply must preempt the handler"
    );
}
